import{z as n,x as d,o as a,c as p,q as t,j as s,D as e,d as i,s as r,S as c}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"MCP 协议设计","description":"","frontmatter":{"title":"MCP 协议设计","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mcp-design.md","filePath":"llm/mcp-design.md","lastUpdated":1791063341000}'),E={name:"llm/mcp-design.md"};function A(m,o,h,B,P,C){const l=d("Mermaid");return a(),p("div",null,[o[2]||(o[2]=t('<h1 id="mcp-协议设计" tabindex="-1">MCP 协议设计 <a class="header-anchor" href="#mcp-协议设计" aria-label="Permalink to &quot;MCP 协议设计&quot;">​</a></h1><div class="epigraph"><p>用 JSON-RPC 做能力协商与运行时发现：宿主管模型与授权，服务器管数据源；工具、资源、提示是三种不同的原语，不是三种函数别名。</p><footer>—— Anthropic，Model Context Protocol 规范与 2024 年 11 月公告；对照 JSON-RPC 2.0</footer></div><p><a href="/llm/mcp">MCP 与工具生态</a> 一文写网络效应与「USB-C」类比。本篇把镜头对准<strong>协议本身</strong>：生命周期、能力位、方法名、传输与内容块。Anthropic 于 2024 年 11 月公布 Model Context Protocol：客户端（嵌在 IDE、桌面宿主里）与服务器（独立进程或远程服务）用 JSON-RPC 2.0 交换消息。它不规定 <a href="/llm/react">ReAct</a> 怎么规划，也不规定模型厂商；它规定如何列出工具、如何调用、如何读资源、如何取提示模板，以及可选的反向采样。没有一篇叫 MCP 的经典 NeurIPS 论文，出处就是公开规范与公告。本篇不把连接器博客的延迟数字写进协议定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Function calling 的 <code>tools</code> 数组是<strong>这一次</strong> HTTP 请求里的静态清单。进程模型缺失：密钥、崩溃、热更新、多数据源隔离都挤在宿主进程里。插件若绑死某一家聊天产品，同一份数据库要写 N 套适配。协议要解决的是进程间契约：如何握手版本、如何声明「我有工具 / 我能订阅资源 / 我禁止你调用模型」、如何把一次调用的 id 与结果对齐、传输在本地管道与远程 HTTP 之间如何换而不改方法名。</p><p>三种信息不能都叫 tool。查询与副作用是工具；大段只读上下文（文件、schema）是资源，应有 URI 与可选订阅；可复用的消息草稿是提示模板，参数化后变成对话前缀。若全做成函数，缓存、权限与日志语义都会错：读第 3 页变成一次「调用」，无法做资源级 ETag 或变更通知。设计问题是原语划分，而不只是再包一层 JSON。</p>',6)),(a(),s(c,null,{default:e(()=>[r(l,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20T%5B%22%E5%B7%A5%E5%85%B7%20tool%EF%BC%9A%E8%83%BD%E6%94%B9%E4%B8%96%E7%95%8C%22%5D%0A%20%20%20%20T1%5B%22%E6%9F%A5%E8%AF%A2%E4%B8%8E%E5%89%AF%E4%BD%9C%E7%94%A8%22%5D%20--%3E%20T2%5B%22tools%20%2F%20call%20%E6%89%A7%E8%A1%8C%22%5D%0A%20%20end%0A%20%20subgraph%20R%5B%22%E8%B5%84%E6%BA%90%20resource%EF%BC%9A%E5%8F%AA%E8%AF%BB%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20%20%20R1%5B%22%E6%96%87%E4%BB%B6%E4%B8%8E%20schema%22%5D%20--%3E%20R2%5B%22URI%20%E8%AF%BB%E5%8F%96%E4%B8%8E%E8%AE%A2%E9%98%85%22%5D%0A%20%20end%0A%20%20subgraph%20P%5B%22%E6%8F%90%E7%A4%BA%20prompt%EF%BC%9A%E6%B6%88%E6%81%AF%E8%8D%89%E7%A8%BF%22%5D%0A%20%20%20%20P1%5B%22%E5%8F%82%E6%95%B0%E5%8C%96%E6%A8%A1%E6%9D%BF%22%5D%20--%3E%20P2%5B%22%E6%8B%BC%E6%88%90%E5%AF%B9%E8%AF%9D%E5%89%8D%E7%BC%80%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...o[0]||(o[0]=[i(" Loading... ",-1)])]),_:1})),o[3]||(o[3]=t('<p><span class="marginnote">JSON-RPC 就是用 JSON 文本来传「调用请求」和「返回结果」的约定：每条请求带 method 名和一个 id，回复用同一个 id 对号入座。MCP 的握手、列清单、调用全都套用这一种消息格式，所以换传输（本机管道或远程 HTTP）时方法名不用改。</span></p><h3 id="先协商能力-再调用方法" tabindex="-1">先协商能力，再调用方法 <a class="header-anchor" href="#先协商能力-再调用方法" aria-label="Permalink to &quot;先协商能力，再调用方法&quot;">​</a></h3><p>未在握手中声明的能力，对端不应调用对应方法。服务器说没有 <code>resources</code>，客户端就不要发 <code>resources/read</code>。客户端若未开放 <code>sampling</code>，服务器不能把补全任务踢回宿主。这一位图比「文档里写了个方法」更硬：版本演进时，旧客户端遇到新方法应得到标准 JSON-RPC 错误，而不是静默忽略导致状态分歧。</p><p><span class="marginnote">规范会改传输（早期 HTTP+SSE 到后续 Streamable HTTP）并加字段。实现必须声明 <code>protocolVersion</code>。不要把某一周的草稿方法当成永远稳定的 ABI。本篇描述公开设计，不跟踪未发布的私有扩展。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>握手：客户端发 <code>initialize</code>，带协议版本、客户端信息与能力；服务器回自身能力与服务器信息；客户端再发 <code>notifications/initialized</code>。之后才是业务方法。工具：<code>tools/list</code> 返回名称、描述、<code>inputSchema</code>（JSON Schema）；<code>tools/call</code> 带名字与参数对象，结果是内容块列表（文本、图像等）加可选错误标志。列表可变更时走 <code>notifications/tools/list_changed</code>，客户端应再 list。资源：<code>resources/list</code> / <code>resources/read</code>，URI 标识；可订阅则有 <code>resources/subscribe</code> 与更新通知。提示：<code>prompts/list</code> / <code>prompts/get</code>，返回消息数组草稿。</p><p>传输：本地开发以 <strong>stdio</strong> 为主，一帧一条 JSON-RPC 消息，便于任意语言写小服务器。远程需要带会话的 HTTP 流，以便多宿主连接同一数据源；具体路径以当时规范为准。日志、进度、取消是控制面：长调用应能被 <code>notifications/cancelled</code> 打断，进度通知不要和最终结果抢同一个 id 语义。错误沿用 JSON-RPC 码（解析 -32700、方法不存在 -32601、非法参数 -32602、内部 -32603）并允许应用层附加 MCP 数据。</p><p><span class="marginnote">stdio 传输可以想象成两个进程之间接了一根水管：宿主把 JSON 消息写进服务器进程的标准输入，服务器把回复写到标准输出。不占端口、不过网卡，数据库密钥可以只留在服务器进程里，宿主崩溃也不会顺手把密钥带崩。</span></p>',8)),(a(),s(c,null,{default:e(()=>[r(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22initialize%20%E8%83%BD%E5%8A%9B%E5%8D%8F%E5%95%86%22%5D%20--%3E%20READY%5B%22notifications%2Finitialized%22%5D%0A%20%20READY%20--%3E%20L%5B%22tools%2Flist%20%C2%B7%20resources%2Flist%20%C2%B7%20prompts%2Flist%22%5D%0A%20%20L%20--%3E%20CALL%5B%22tools%2Fcall%20%2F%20resources%2Fread%22%5D%0A%20%20CALL%20--%3E%20OUT%5B%22%E5%86%85%E5%AE%B9%E5%9D%97%E7%BB%93%E6%9E%9C%22%5D%0A%20%20OUT%20--%3E%20HOST%5B%22%E5%AE%BF%E4%B8%BB%E8%AF%91%E6%88%90%E6%A8%A1%E5%9E%8B%20tool%20%E8%A7%82%E5%AF%9F%22%5D%0A"})]),fallback:e(()=>[...o[1]||(o[1]=[i(" Loading... ",-1)])]),_:1})),o[4]||(o[4]=t('<h3 id="内容块与模型信封的翻译点" tabindex="-1">内容块与模型信封的翻译点 <a class="header-anchor" href="#内容块与模型信封的翻译点" aria-label="Permalink to &quot;内容块与模型信封的翻译点&quot;">​</a></h3><p>服务器返回的是协议内容块，不是 Chat Completions 的 <code>role: tool</code>。翻译发生在<strong>客户端</strong>：文本块变成 tool 观察字符串，图像块变成多模态消息部分，错误标志变成模型能读的失败说明。<code>inputSchema</code> 与 function calling 的 <code>parameters</code> 同构，所以列表可以一对一登记进当轮 <code>tools</code>。资源则通常注入为上下文，而不是一次函数调用——除非宿主故意把 <code>read</code> 包成工具。这一翻译层是设计的一部分：协议稳定，模型厂商可以换。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对模型，MCP 往往透明：它仍在 function calling 分布上采样名字与 JSON。协议改变的是<strong>条件前缀从哪来、副作用在哪执行</strong>。发现使工具集随连接的服务器变化；隔离使密钥留在服务器进程；JSON-RPC <code>id</code> 使并行 call 可以对齐。<code>sampling/createMessage</code> 把方向反过来：服务器请宿主代调模型。这在不可信服务器上等于出借补全能力，默认应关。Roots 向服务器声明工作区根路径，缩小文件类服务器的可见范围，是权限设计而不是检索算法。</p><p>通知（notification）无响应、无 id 匹配义务，适合 list_changed、进度、日志。若把通知误当成请求去等结果，客户端会死锁。批量 RPC 在现代 MCP 传输里并不作为一等依赖；实现应以单消息帧为准。schema 稳定性决定生态：同一工具在不同宿主描述不同，模型调用分布就会漂移——这是协议无法单独修复的，需要服务器作者把描述当 API 的一部分来版本化。</p><p><span class="marginnote">常见误区：把通知当请求去等回复。通知没有 id、协议也不给回执，「发完就完」——进度、日志、清单变更都是单向广播。客户端若傻等一个永远不会来的响应，握手之后第一步就会卡死，这类死锁在日志里往往一行错误都没有。</span></p><p><span class="marginnote">MCP 不替代鉴权网关、不替代结构化解码、不替代多步规划。它只保证有一份可发现的进程契约。内部单个 Agent 运行时若永不复用连接器，直接函数分发更短；为「生态」把高权限 shell 暴露成通用服务器，是设计误用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><h3 id="传输换了-威胁模型也要换" tabindex="-1">传输换了，威胁模型也要换 <a class="header-anchor" href="#传输换了-威胁模型也要换" aria-label="Permalink to &quot;传输换了，威胁模型也要换&quot;">​</a></h3><p>远程传输的威胁模型与 stdio 不同：数据面进网络，要 TLS、鉴权、审计，不能因为「官方连接器」就共用本地信任假设。资源读取能打满上下文，必须有体积与超时。工具副作用的确认 UI 属于宿主，协议只把 call 送到服务器。评测应拆开：互操作（能否 initialize/list/call）、模型用工具成功率、服务器业务正确性。stdio 上「用户已登录本机」的隐含信任，搬到公网会立刻失效。</p><p>与纯 function calling：无 MCP 也能做工具，只是清单写死在宿主。与 <a href="/llm/tool-call-sft">tool-call-sft</a>：训练的是模型如何填 schema，不是进程如何握手。规范演进期间，客户端应对未知能力降级，而不是声称实现「全部 MCP」。</p><p><span class="marginnote">出处：Anthropic Model Context Protocol 公开规范与 2024-11 公告；JSON-RPC 2.0（RFC 风格的 <code>jsonrpc: &quot;2.0&quot;</code> 消息模型）。无会议长文作为协议定义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MCP 用 JSON-RPC 握手能力，再发现并调用 tools / resources / prompts。</li><li>宿主译成模型信封；服务器持有数据源密钥；sampling 默认关闭。</li><li>传输（stdio 与远程 HTTP 流）可换，方法名与内容块语义应保持。</li><li>协议不管规划算法与检索，只管进程间契约与隔离。</li><li>出处：Anthropic MCP 规范；JSON-RPC 2.0。</li></ul>',14))])}const g=n(E,[["render",A]]);export{T as __pageData,g as default};
